import { type ComponentProps, createElement, forwardRef } from 'react';

import styled from '@emotion/styled';
import { composeStyles } from 'utils/emotion/applyVariants';

type OverflowVariant = 'autoY' | 'autoX' | 'hidden';
type BackgroundVariant = 'white' | 'none';
type PositionVariant = 'relative';

interface ContainerWithScrollStyledProps {
  $overflow?: OverflowVariant;
  $background?: BackgroundVariant;
  $padding?: boolean;
  $borderRadius?: boolean;
  $position?: PositionVariant;
}

const StyledContainerWithScroll = styled.div<ContainerWithScrollStyledProps>(
  composeStyles(
    {
      width: '100%',
      scrollbarColor: 'initial',

      '&::-webkit-scrollbar': {
        height: '8px',
        width: '8px',
      },

      '&::-webkit-scrollbar-track': {
        background: '#1414140A',
        borderRadius: '512px',
      },

      '&::-webkit-scrollbar-thumb': {
        background: '#1414143D',
        borderRadius: '512px',
      },

      '&.has-scroll': {
        paddingBottom: '20px',
      },
    },
    {
      $overflow: {
        autoY: {
          overflowY: 'auto',
        },
        autoX: {
          overflowX: 'auto',
        },
        hidden: {
          overflowY: 'hidden',
          overflowX: 'hidden',
        },
      },
      $background: {
        white: {
          backgroundColor: 'white',
        },
        none: {
          backgroundColor: 'transparent',
        },
      },
      $padding: {
        false: {
          padding: '0px',
        },
        true: {
          padding: '24px',
        },
      },
      $borderRadius: {
        true: {
          borderRadius: '0 0 16px 16px',
        },
        false: {
          borderRadius: '0',
        },
      },
      $position: {
        relative: {
          position: 'relative',
        },
      },
    },
  ),
);

export type ContainerWithScrollProps = ComponentProps<'div'> & {
  overflow?: OverflowVariant;
  background?: BackgroundVariant;
  padding?: boolean;
  borderRadius?: boolean;
  position?: PositionVariant;
};

export const ContainerWithScroll = forwardRef<
  HTMLDivElement,
  ContainerWithScrollProps
>(function ContainerWithScroll(
  { overflow, background, padding, borderRadius, position, ...rest },
  ref,
) {
  return createElement(StyledContainerWithScroll, {
    $overflow: overflow,
    $background: background,
    $padding: padding,
    $borderRadius: borderRadius,
    $position: position,
    ref,
    ...rest,
  });
});
